308: function settle(uint256 which) public {
309:         if (REDEMPTION.requestCount() == 0) {
310:             _redeemAgainst(which % NUM_HOLDERS, _anActiveAsset(), which);
311:         }
312:         uint256 count = REDEMPTION.requestCount();
313:         if (count == 0) return; // the bootstrap redemption was refused; nothing to settle
314:         uint256 id = which % count;
315: 
316:         if (expectedSettled[id]) {
317:             // Already settled: the contract must refuse. A second settlement
318:             // succeeding would mean the off-chain leg could be claimed twice.
319:             try REDEMPTION.settleRedemption(id) {
320:                 ledgerInconsistent = true;
321:             } catch {
322:                 // expected
323:             }
324:         } else {
325:             REDEMPTION.settleRedemption(id);
326:             expectedSettled[id] = true;
327:             ghostSettlements++;
328:         }
329: 
330:         _verifyRequest(id);
331:         _afterCall();
332:     }

